package main

import("context";"encoding/json";"log";"net/http";"strings";"time";"github.com/golang-jwt/jwt/v5";"github.com/google/uuid";"github.com/nawyaunnam/cloudscale-distributed-job-processing/internal/config";"github.com/nawyaunnam/cloudscale-distributed-job-processing/internal/model";"github.com/nawyaunnam/cloudscale-distributed-job-processing/internal/store";"github.com/segmentio/kafka-go")
func main(){ctx:=context.Background();c:=config.Load();s,e:=store.New(ctx,c.DatabaseURL);if e!=nil{log.Fatal(e)};w:=&kafka.Writer{Addr:kafka.TCP(strings.Split(c.KafkaBrokers,",")...),Topic:"jobs",Balancer:&kafka.Hash{},RequiredAcks:kafka.RequireAll};defer w.Close();mux:=http.NewServeMux();mux.HandleFunc("/health",func(x http.ResponseWriter,_ *http.Request){x.Write([]byte(`{"status":"ok"}`))});mux.Handle("/v1/jobs",auth(c.JWTSecret,http.HandlerFunc(func(x http.ResponseWriter,r *http.Request){if r.Method!=http.MethodPost{http.Error(x,"method",405);return};var q model.SubmitRequest;if json.NewDecoder(http.MaxBytesReader(x,r.Body,1<<20)).Decode(&q)!=nil||q.Type==""{http.Error(x,"invalid",400);return};tenant:=r.Context().Value("tenant").(string);key:=r.Header.Get("Idempotency-Key");if key==""{http.Error(x,"Idempotency-Key required",400);return};if q.MaxAttempts<1{q.MaxAttempts=4};j,_,e:=s.Create(r.Context(),model.Job{ID:uuid.NewString(),TenantID:tenant,Type:q.Type,Payload:q.Payload,MaxAttempts:q.MaxAttempts},key);if e!=nil{http.Error(x,"store",500);return};b,_:=json.Marshal(j);if e=w.WriteMessages(r.Context(),kafka.Message{Key:[]byte(j.ID),Value:b});e!=nil{http.Error(x,"broker",503);return};x.Header().Set("Content-Type","application/json");x.WriteHeader(202);x.Write(b)})));mux.Handle("/v1/jobs/",auth(c.JWTSecret,http.HandlerFunc(func(x http.ResponseWriter,r *http.Request){j,e:=s.Get(r.Context(),strings.TrimPrefix(r.URL.Path,"/v1/jobs/"),r.Context().Value("tenant").(string));if e!=nil{http.Error(x,"not found",404);return};json.NewEncoder(x).Encode(j)})));log.Fatal((&http.Server{Addr:":8080",Handler:mux,ReadHeaderTimeout:3*time.Second}).ListenAndServe())}
func auth(secret string,next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){raw:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ");t,e:=jwt.Parse(raw,func(*jwt.Token)(any,error){return []byte(secret),nil});if e!=nil||!t.Valid{http.Error(w,"unauthorized",401);return};claims:=t.Claims.(jwt.MapClaims);ctx:=context.WithValue(r.Context(),"tenant",claims["tenant"].(string));next.ServeHTTP(w,r.WithContext(ctx))})}

